def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my, last_op = history[-1]

    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # Endgame: defect on the very last round
    if n == 99:
        return 'D'

    # Exploit unconditional cooperators
    if opp_def == 0:
        if my_def == 0:
            if n == 8:
                return 'D'
            return 'C'
        elif my_def == 1:
            if n == 9:
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    # Periodicity detection
    if n >= 15:
        for k in range(2, 9):
            if n >= 3 * k:
                ok = True
                for i in range(k, n):
                    if op[i] != op[i-k]:
                        ok = False
                        break
                if ok:
                    return 'D'

    # Consecutive defection streak
    streak = 0
    for i in range(n-1, -1, -1):
        if op[i] == 'D':
            streak += 1
        else:
            break
    if streak >= 5:
        return 'D'

    # Core TFT with forgiveness
    if last_op == 'D':
        recent_my_def = False
        if n >= 1 and my[-1] == 'D':
            recent_my_def = True
        if n >= 2 and my[-2] == 'D':
            recent_my_def = True
        if recent_my_def:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
